      if (!list.length) {
        try { list = (pageWindow.W?.model?.mapUpdateRequests?.getObjectArray?.() || []).filter(model => model.attributes?.open !== false && model.attributes?.resolution == null).map(model => ({ id: String(model.attributes.id ?? model.getID?.()), at: model.attributes.geoJSONGeometry?.type === 'Point' ? model.attributes.geoJSONGeometry.coordinates : null })); } catch (_) { list = []; }
      }
