      openId:()=>{ try { readCurrent(); } catch (_) {   } const id=active?.type==='mapUpdateRequest'||active?.id!=null?active?.id:sdkOpen; return id!=null&&/^\d+$/.test(String(id))?Number(id):NaN; },
